import math
import re
import sys
import collections
import itertools
def is_not_prime(n):
    """Write a python function to identify non-prime numbers."""
    if n <= 1:
        return True
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return True
    return False

